-- Prepend the actual source texture list (generated by test_energy_effects.py).
-- Run in the real Studio Client. This proves asset loading, not appearance.
local provider=game:GetService('ContentProvider')
local report={assets={},liveEnergyEmitters={},validation='Native asset fetch; visible particle/bloom screenshots remain required'}
for _,texture in ipairs(energyTextures) do
 local status
 local ok,err=pcall(function()
  provider:PreloadAsync({texture},function(_,result) status=result end)
 end)
 table.insert(report.assets,{texture=texture,status=tostring(status),ok=ok,error=not ok and tostring(err) or nil})
 assert(ok and status==Enum.AssetFetchStatus.Success,'Energy texture failed to load: '..texture..' / '..tostring(status)..' / '..tostring(err))
end
local names={CuttingSparks=true,WorkSparks=true,OriginParticles=true,OriginGlow=true,MoltenSparks=true,TurbulentColumnEnergy=true}
for _,object in ipairs(workspace:GetDescendants()) do
 if object:IsA('ParticleEmitter') and names[object.Name] then
  table.insert(report.liveEnergyEmitters,{name=object.Name,path=object:GetFullName(),texture=object.Texture,enabled=object.Enabled,
   rate=object.Rate,timeScale=object.TimeScale,brightness=object.Brightness,lightEmission=object.LightEmission,
   lightInfluence=object.LightInfluence,flipbook=tostring(object.FlipbookLayout)})
 end
end
return report
